update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Data edited to account for failed fuel flow to load test reported 1st quarter.  Fuel flowmeter recertfified during 2nd quarter.' where Mon_Plan_Id = 'HDQPLTJMEN-C9C95B204DFE410E93900773A1A9F973' and Rpt_Period_Id = 126 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Informational errors were generated for fuel flow and related heat input.  Basin has checked into the elevated values and they appear valid and due to cold ambient temperatures.  We will continue to monitor and investigate.' where Mon_Plan_Id = 'HDQPLTJMEN-C9C95B204DFE410E93900773A1A9F973' and Rpt_Period_Id = 128 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Informational errors were generated for fuel flow and related heat input.  Basin has checked into the elevated values and they appear valid and due to cold ambient temperatures.  We will continue to monitor and investigate.  Values slightly higher than maximum.  Similiar issue occured 4th quarter 2024.' where Mon_Plan_Id = 'HDQPLTJMEN-C9C95B204DFE410E93900773A1A9F973' and Rpt_Period_Id = 132 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Third Quarter EDR submitted in November for ORISPL 56610 due to fatal reporting error due to missing PEI records.  PEI conducted on component ID A13 on 5/8/2014.  PEI was not conducted on component A14 as needed.  Passed PEI tests conducted on both components ID A13 and A14 on 11/3/16.  Missing data applied to third quarter emissions file for both components A13 and A14.   ' where Mon_Plan_Id = 'HDQPLTJROS-4523F4D1FC9641AA92A370D68210C1AE' and Rpt_Period_Id = 95 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'ECMPS caught calibration gas bottle error where oxygen high range calibration gas exceeded maximum range by 0.5%.  Teledyne CEM reporting software did not alarm when gas was used for quarterly linearity test and daily calibrations.  Emissions data has been marked missing and invalid.' where Mon_Plan_Id = 'HDQPLTJROS-4523F4D1FC9641AA92A370D68210C1AE' and Rpt_Period_Id = 108 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Unit offline for engine repair.' where Mon_Plan_Id = 'HDQPLTSSMO-F5EBFC0ACA204DE89ADA524FF605F71A' and Rpt_Period_Id = 120 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Unit offline for engine repair.' where Mon_Plan_Id = 'HDQPLTSSMO-F5EBFC0ACA204DE89ADA524FF605F71A' and Rpt_Period_Id = 121 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'It was discovered that the Unit 2 Low Range NOx calibration bottle that was in service from 7/24/24 through the end of the quarter was out of tolerance.  The bottle must be within 80% and 100% of the NOx low range span value of 5 ppm, but the bottle used was ~72% of the span value with a NOx concentration of 3.633 ppm.  The bottle vendor and key site personnel have been engaged to avoid future occurrences.  Note that the requested concentration on the bottle COA is within the 80%-100% target, but the actual concentration was out of tolerance.  The applicable NOx data during this time period has been invalidated and substituted following data substitution procedures.' where Mon_Plan_Id = 'HOUWTC-L-8-3C2D69DCF97C4A948FE0B02E4FEAE9E2' and Rpt_Period_Id = 127 and coalesce( Submission_Id, 0 ) <= 0;
