update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'During the 09/27/19 06 hour and a unit shutdown; the NOXR data is missing. Due to the low load operation, there is no quality assured data in the corresponding load bin. As a result, the maximum hourly value in the lookback period within the next higher load bin was substituted (MODC 10). - 10/18/19 SFinley' where Mon_Plan_Id = 'L00348-D8362E7255084C75AFE1001757638494' and Rpt_Period_Id = 107 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'The ""INFROM HOURMHV-16-D"" showed the stack flow rate during a single hour more than the MP maximum. It was determined that no change is required at this time due to the limited number of events. This will be reviewed in greater detail during the annual flow range review in January 2022. - SFinley 07/23/21' where Mon_Plan_Id = 'L00348-D8362E7255084C75AFE1001757638494' and Rpt_Period_Id = 114 and coalesce( Submission_Id, 0 ) <= 0;
