update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Based on December 2021 email discussions with Travis Johnson (ECMPS); the NOx span and range are being changed from 0-150 to 0-100 ppm. New daily calibration and linearity cylinder gases are on order and scheduled to be delivered in March 2022. Once received, the analyzer, CEMS, and MP will be updated to the new range. ? SFinley 01/19/2022' where Mon_Plan_Id = 'L00348-D8362E7255084C75AFE1001757638494' and Rpt_Period_Id = 116 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'In response to the INFORM error (HOURDHV-14-F); MODC 10 was used because there is no quality assured data in the corresponding (low load) bin. ? SFinley 04/14/2022' where Mon_Plan_Id = 'L00348-D8362E7255084C75AFE1001757638494' and Rpt_Period_Id = 117 and coalesce( Submission_Id, 0 ) <= 0;
