update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'We are having difficultly generating the Gas Flow To Load data for both Unit 1 and Unit 2 Oris Code 246.  The DAHS vendor is aware of the problem and is researching a correction to the system.  We are therefore submitting this quarter without this QA record.  We fully expect to pass the calculation once we resolve the errors.  We will submit the records once the problems are resolved.  Richard Flander Submit Agent PG&E.' where Mon_Plan_Id = 'MDC-0833ED67FF9644848B8B8C478AB5002B' and Rpt_Period_Id = 65 and coalesce( Submission_Id, 0 ) <= 0;
