update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'The QA parameter ranges for water to fuel ratio were set at 0.84 to 1.18 for S42 and 0.83 to 1.18 for S43, based on emissions testing completed on January 28, 2009 for S42 and January 30, 2009 for S43.  The upper limit of the range was changed to 1.3 for both units as of January 1, 2010.  This takes into account the fact that the w/f ratio can increase up to a limit of 1.3 during hot weather.  This change was made based on discussion with the manufacturer and not as a result of changes to the water/fuel schedule. Reporting of emissions during calendar year 2009 was not affected, since the water/fuel ratio during 2009 did not exceed 1.18 on an hourly basis at any time.' where Mon_Plan_Id = 'MDC-0920ED50A1DA45FB8D2FFEE659F9E944' and Rpt_Period_Id = 69 and coalesce( Submission_Id, 0 ) <= 0;
