update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Discovered software error in how NOx correlation was being applied. Requested resubmission of second quarter data prior to submitting third quarter XML EDR file.' where Mon_Plan_Id = 'MDC-35662D24D13F41F9936F38C01D6E372E' and Rpt_Period_Id = 71 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'In January of 2016, Jackson Generating Station (JGS) discovered that the historic procedure of calibrating the duct burner fuel flow meters did not wholly conform to the requirements in 40 CFR Part 75, Appendix D, Section 2.1.5.  Based upon subsequent discussions with Mr. Louis Nichols and Mr. Robert Vollaro of CAMD, JGS has invalidated hourly fuel flow rate data (comprised of separate fuel flow meters on each combustion turbine and duct burner) whenever the duct burners were in service for any length of time.  Missing fuel flow rate data for such hours has been calculated as the arithmetic average of the hourly fuel flow rate measured and recorded by a certified fuel flowmeter system at the corresponding operating unit load range during the 720 operating hours preceding expiration of valid duct burner fuel flow meter calibrations' where Mon_Plan_Id = 'MDC-358806F4CB95434DBDDC570ADC1539EC' and Rpt_Period_Id = 73 and coalesce( Submission_Id, 0 ) <= 0;
