update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'The ""INFROM HOUROP-44B"" error annunciated when ECMPS made a last minute change to the QA/QC checks which left the DAHS vendor unable to get the updated software published to all facilities. Our vendor has corrected for this QA/QC check. Since this is currently an inform type error, the software patch will be installed after the 2017Q2 reports are complete. SFinley 07/10/17' where Mon_Plan_Id = 'MDC-39672F674EF241088E173A60F3CC999B' and Rpt_Period_Id = 98 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'The ""INFROM HOUROP-44B"" error annunciated when ECMPS made a last minute change to the QA/QC checks in 2017Q2 which left the DAHS vendor unable to get the updated software published to all facilities. Our vendor has corrected for this QA/QC check. Since this is currently an inform type error, the software patch will be installed sometime after the 2017Q3 reports are complete. SFinley 10/03/17' where Mon_Plan_Id = 'MDC-39672F674EF241088E173A60F3CC999B' and Rpt_Period_Id = 99 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'The informational error HOURCV-37-C is related to three hours in 2021Q4 where the NOxR was greater than the MER. Each of these hours include a partial operating hour where the unit operated for only 3, 7, and 7 minutes. These periods of operation are defined as startup which was confirmed by high O2 readings at the same time.  As a result of this review, there is no reason to modify the MP MER. ? SFinley 01/20/2022' where Mon_Plan_Id = 'MDC-39672F674EF241088E173A60F3CC999B' and Rpt_Period_Id = 116 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'This Unit was starting back up from a planned outage and equipment upgrade at the beginning of August. The Unit was undergoing tuning through August 4th. The manner in which the steam turbine load was apportioned resulted in unexpected excessive load. After the tuning period the load data consistently remained in the expected range in the current Monitoring Plan. Only one hour returned in a Critical Error 8/3/2016 hour 16. ' where Mon_Plan_Id = 'MDC-39A0D0CF2AD442B0A8B07A7E132FFA05' and Rpt_Period_Id = 95 and coalesce( Submission_Id, 0 ) <= 0;
