update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'ID FAN problems during hours in which informational errors occur.  Calibrations and Interference Checks were acceptable during the time period so the flowrate data was not invalidated.  Reported data is higher than what would be reported using missing data substitution for those hours.  A monitoring plan update was not made at this time because the errors are a result of process operations which are not considered normal.' where Mon_Plan_Id = 'MDC-3A931CAB1C6143A0A844FDA41208CDF3' and Rpt_Period_Id = 74 and coalesce( Submission_Id, 0 ) <= 0;
