update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'GGS recognizes potential issues through evaluation of the CO2 control chart diagnostic tool and is diligently pursuing an investigation into this matter and the extent of any impact on the quarterly reporting, but at this time is not definitively able to disqualify any data. Biomass boiler emissions can fluctuate greatly with fuel quality/boiler conditions. Grayling will update the Q4 EDR submission with any findings that may impact emissions reporting and/or CEMS downtime prior to the next EDR submittal.' where Mon_Plan_Id = 'MDC-3BC100E61CA34AF59C68DE1E086477BB' and Rpt_Period_Id = 124 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'On 11/5/12 we are reporting a NOX ppm value, and NOx rate that exceeds the MPC and MER we are reporting in the monitoring plan.  The reason for the high emissions for this hour is attributed to the Unit tripping offline during a startup.  The values reported are not representative of unit operation, therefore an update to the monitoring plan will not be made.' where Mon_Plan_Id = 'MDC-3CD4BA66A4124CE1BEBB321E098AC2CD' and Rpt_Period_Id = 80 and coalesce( Submission_Id, 0 ) <= 0;
