update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Plant evaluations will continue to be conducted on a regular basis for HI. HI maimium was based on original design information.' where Mon_Plan_Id = 'MDC-4A9890D284BB4A5C9A72C81302133C6F' and Rpt_Period_Id = 69 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'During 4th Quarter, data review revealed incorrect data flagging, and some incorrect process parameters for 3rd Quarter 2011 hourly emissions data previously submitted on 10/29/2011.  Q3 2011 Emissions EDRs for FRPP 1 and FRPP 2 resubmitted in January 2011.' where Mon_Plan_Id = 'MDC-4A9890D284BB4A5C9A72C81302133C6F' and Rpt_Period_Id = 75 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'During 3rd Quarter, there were two hours of heat input data above the maximum value listed in the monitoring plan.  These hours were during a period when the fuel flowmeter data was missing and heat input was substituted based on correlated values.  For both hours, the unit was operating at a very high load, with very few hours at a similar load in the recent past.  No change is being made to the monitoring plan due to this substituted data, but we will continue to monitor this and will update the monitoring plan if actual data indicate a change is warranted.' where Mon_Plan_Id = 'MDC-4A9890D284BB4A5C9A72C81302133C6F' and Rpt_Period_Id = 83 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'A daily calibration error test was initiated on 7/23/14 Hour 6 for FRPP Unit 2.  During the calibration sequence, an issue was discovered with the sampling system that prevented proper sample flow from reaching the analyzers while in calibration mode.  The issue was immediately remedied, and a subsequent daily calibration error test was initiated and passed during Hour 6, with data validation criteria still being met for the hour.  Due to the fact that the injection results for the incomplete initial calibration error test were not within the applicable performance specification, the test has been reported as failed with a test result code of ""Aborted"", and this record has been included in the 2014 Q3 EDR submission.   ' where Mon_Plan_Id = 'MDC-4A9890D284BB4A5C9A72C81302133C6F' and Rpt_Period_Id = 87 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Cartwright and Associates' where Mon_Plan_Id = 'MDC-4A9A3268A600433CB5A421F94F845F4E' and Rpt_Period_Id = 61 and coalesce( Submission_Id, 0 ) <= 0;
