update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'SHGP discovered during a recent audit that heat recovery steam generator flow elements were annubars, not orifice plates as listed in the monitoring plan for which calibration documents could not be located. Therefore, SHGP is resubmitting EDRs for a period of five years, consistent with recordkeeping requirements, with substituted fuel flow data pursuant to missing data substitution procedures under Part 75 and is updating the monitoring plan to reflect the flow elements as annubars. Required calibrations on the annubars have since been performed and certified. SHGP discussed this matter with CAMD analysts on June 25, 2020.' where Mon_Plan_Id = 'MDC-5E0A95B32A50444F83A1D3222F2552E8' and Rpt_Period_Id = 88 and coalesce( Submission_Id, 0 ) <= 0;
