update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'SHGP discovered during a recent Greenhouse Gas audit that the EPN 801 total heat input value did not correspond with the summation of hourly heat input data in 3Q 2014.  Therefore, SHGP is resubmitting the 3Q 2014 EPN 801 EDR to update the Quarterly Emissions Summary table for only total heat input.  The hourly emissions will not change as a result of this resubmission.' where Mon_Plan_Id = 'MDC-93ABD90ABA354FEEA922AF0129F33962' and Rpt_Period_Id = 87 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'SHGP discovered during a recent audit that heat recovery steam generator flow elements were annubars, not orifice plates as listed in the monitoring plan for which calibration documents could not be located. Therefore, SHGP is resubmitting EDRs for a period of five years, consistent with recordkeeping requirements, with substituted fuel flow data pursuant to missing data substitution procedures under Part 75 and is updating the monitoring plan to reflect the flow elements as annubars. Required calibrations on the annubars have since been performed and certified. SHGP discussed this matter with CAMD analysts on June 25, 2020.' where Mon_Plan_Id = 'MDC-93ABD90ABA354FEEA922AF0129F33962' and Rpt_Period_Id = 88 and coalesce( Submission_Id, 0 ) <= 0;
