update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Report made on 07/30/2009 at 06:38:21' where Mon_Plan_Id = 'MDC-A82EB12F40DC4C6CA2770845D3B14491' and Rpt_Period_Id = 65 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Report made on 07/30/2009 at 09:39:22' where Mon_Plan_Id = 'MDC-A82EB12F40DC4C6CA2770845D3B14491' and Rpt_Period_Id = 66 and coalesce( Submission_Id, 0 ) <= 0;
