update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Received permission from Travis Johnson, EPA Region 6 to submit recalculated PNG fuel flow from 1/25/2010 - 3/13/2010.  The recalculation was necessary due to a crash with the control system that caused factors to revert back to default values.  The fuel flow values that were being sent from the control system to the CEMS datalogger were incorrect.  The affected time period was between 1/25/2010 - 3/13/2010.  The factors were corrected on 3/13/2010.  This affected Dell Unit 2 only.  If you have any questions please contact Sharon Moss. phone:  417-885-9315/ email:  smoss@aeci.org' where Mon_Plan_Id = 'MDC-B3FAA994190047968B25C8B6C42CECDA' and Rpt_Period_Id = 69 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'In refernce to ECMPS RT 67881, this emissions file is being resubmitted to apply the appropriate BAF to the hourly data. There were two cert events, 100 (analyzer replacement) and 105 (umbilical line replacement). The cert event 105 was driving the use of the BAF from a previous RATA in May. Scott Aber removed the cert event from the host system and the emissions data now has the correct BAF. This was done after the quarter because the September GCV was not entered so when entering that, this error came up.' where Mon_Plan_Id = 'MDC-B4147730E09A4AEFBCFE88A76A60C840' and Rpt_Period_Id = 115 and coalesce( Submission_Id, 0 ) <= 0;
