update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'This EDR contains informational errors (HOURDHV-18-K, HOURDHV-24-K and HOURDHV-32-C) that relate to a failure to conform to the new reporting instructions and XML schema for missing data periods. Our DAHS vendor (Environmental Systems Corporation, or ESC) did not release a patch to address the changes to the reporting requirements for missing data periods until late September of 2019.  We have not yet had a chance to deploy the patch as the DAHS server needs other software updates before the patch can be deployed.  Our intent is to ensure that the patch is deployed before submitting the EDR for the 4th quarter of 2019.' where Mon_Plan_Id = 'MDC-B4F1EF2F98984724945B49AD411E8F7B' and Rpt_Period_Id = 107 and coalesce( Submission_Id, 0 ) <= 0;
