update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Note that there were a few hours around April 1 through April 3 where the NOx concentration exceeded the high value listed in the monitoring plan.  These occurred after the unit installed new SOFA burners and prior to tuning.  They were a one time anomoly and no upward adjusment of the Max concentration is required at this time.  NOx levels are now lower as a result of the SOFA burners being tuned.' where Mon_Plan_Id = 'MDC-C1207E15B07B41D0953507FF6D8CDCE9' and Rpt_Period_Id = 66 and coalesce( Submission_Id, 0 ) <= 0;
