update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Near the end of December, Cherokee Unit 3 experienced an ID fan problem.  This led the Flowrate CEMS to record higher flowrate than would normally have been expected.  Because the CEMS did not experience any problems during this time, we have chosen to report the data for this period as valid data because it conservatively over-reports Heat Input and mass emissions.' where Mon_Plan_Id = 'MDC-C1F508624D6C4EFB9DF92DBAF53D9893' and Rpt_Period_Id = 80 and coalesce( Submission_Id, 0 ) <= 0;
