update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Discovered CET that was submitted as valid but should have been marked aborted. Resubmitted Emission file contains 1 extra hour of downtime.' where Mon_Plan_Id = 'MDC-E93B4DDD0E924BB5A0CB2F079965B2DD' and Rpt_Period_Id = 114 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'The HI hour that exceeded the maximum value in the monitoring plan was due to a  high CO2 analyzer value.  The CO2 calibration value during this same hour showed that the analyzer was too high.  The analyzer was recalibrated and the HI value remained below the maximum value.' where Mon_Plan_Id = 'MDC-E983030272F5454EBF03FDE2896F66E5' and Rpt_Period_Id = 84 and coalesce( Submission_Id, 0 ) <= 0;
update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'On Wednesday, March 17, 2010 a contractor for Ameren that was working on the PI data collection software noticed the CEM server was operating on Central Standard Time (CST).  He reset the time on the server to Daylight Savings Time.  Ameren discovered the problem on Monday and reset the time to CST.  With the approval of Bob Vollaro we invalidated hours 12 and 13 on March 17 and hour 12 on March 22 and left the data in between as valid data.' where Mon_Plan_Id = 'MDC-EA269B9F5C614FBAAADF9B21AA5CEAA7' and Rpt_Period_Id = 69 and coalesce( Submission_Id, 0 ) <= 0;
