update camdecmps.EMISSION_EVALUATION set Submission_Comment = 'Unit HGS1 did not operate during 2014 QTR 1. The DAHS had communications failures on 01/09/2014 14:57 to 16:09 and 03/15/2014 09:15 to 12:55. Per phone conversation with Jenny Jachim (EPA) on 04/28/2014, a non-operating reporting period would need to be generated. Working with DAHS vendor on 04/28/2014 and 04/29/2014, we were able to export correct emissions XML that showed no operating hours during DAHS comms failures. This XML file was uploaded into ECMPS on 04/29/2014, showed no errors during evaluation, and ECMPS correctly indicated the quarter was a non-operating quarter. (GNB 04/29/2014)' where Mon_Plan_Id = 'MODEL13-A1F8D161C3B24E018029350F1AC73F24' and Rpt_Period_Id = 85 and coalesce( Submission_Id, 0 ) <= 0;
